  'help.type.security': 'Turvallisuus',
  'help.type.other': 'Muu',
  'help.faq.cantLogin.q': 'En voi kirjautua tililleni',
  'help.faq.cantLogin.a': 'Varmista, että käytät oikeaa sähköpostia ja salasanaa. Jos unohdit salasanasi, napsauta "Unohditko salasanan?" kirjautumisnäytöllä. Jos ongelma jatkuu, luo tukilippu.',
  'help.faq.notReceiving.q': 'En saa sähköposteja',
  'help.faq.notReceiving.a': 'Tarkista ensin Roskaposti-kansio. Varmista, ettei tallennustilasi ole täynnä. Jos ongelma jatkuu, varmista, että lähettäjällä on oikea sähköpostiosoite ja luo tukilippu.',
  'help.faq.cantSend.q': 'En voi lähettää sähköposteja',
  'help.faq.cantSend.a': 'Varmista internet-yhteytesi ja että vastaanottajan sähköpostiosoite on oikea. Tarkista, onko liitteitä, jotka ovat liian suuria (max 25MB). Yritä uudelleen muutaman minuutin kuluttua.',
  'help.faq.forgotPassword.q': 'Unohdin salasanani',
  'help.faq.forgotPassword.a': 'Kirjautumisnäytöllä napsauta "Unohditko salasanan?" ja seuraa ohjeita salasanasi palauttamiseksi palautussähköpostiosoitteesi kautta.',
  'help.faq.accountSecurity.q': 'Luulen, että tilini on vaarantunut',
  'help.faq.accountSecurity.a': 'Vaihda heti salasanasi. Tarkista Lähetetyt-kansiosi viestit, joita et lähettänyt. Ota käyttöön kaksivaiheinen todennus Asetukset > Turvallisuus. Tarvittaessa luo kiireellinen tukilippu.',
  'help.faq.appAccess.q': 'Miten pääsen sovellukseen mobiilissa?',
  'help.faq.appAccess.a': 'Voit käyttää Chatyy\'tä minkä tahansa mobiiliselaimen kautta osoitteessa chatyy.com.br tai ladata sovelluksemme laitteesi sovelluskaupasta.',

  // Privacy modal
  'privacy.title': 'Tietosuojakäytäntö',
  'privacy.subtitle': 'Miten suojaamme ja käsittelemme tietojasi',
  'privacy.lastUpdated': 'Viimeksi päivitetty: Maaliskuu 2026',
  'privacy.dataCollection.title': 'Tietojen kerääminen',
  'privacy.dataCollection.body': 'Keräämme vain tiedot, jotka ovat tarpeen sähköpostipalvelumme tarjoamiseksi: nimesi, sähköpostiosoitteesi ja viestien sisältö, joita lähetät ja vastaanotat. Emme myy tai jaa henkilötietojasi kolmansille osapuolille markkinointitarkoituksiin.',
  'privacy.dataUsage.title': 'Miten käytämme tietojasi',
  'privacy.dataUsage.body': 'Tietojasi käytetään yksinomaan sähköpostipalvelun toimintaan ja parantamiseen, mukaan lukien viestien toimittaminen, roskapostin suodattaminen, AI-pohjaisten ominaisuuksien tarjoaminen (suostumuksellasi) ja tilin turvallisuuden ylläpitäminen.',
  'privacy.dataSecurity.title': 'Tietoturva',
  'privacy.dataSecurity.body': 'Käytämme alan standardin mukaista salausta (TLS/SSL) kaikille siirrettäville ja levossa oleville tiedoille. Istunnot on suojattu salatuilla tokeneilla ja CSRF-suojauksella. Tarkastamme säännöllisesti turvallisuuskäytäntöjämme.',
  'privacy.cookies.title': 'Evästeet & Paikallinen tallennus',
  'privacy.cookies.body': 'Käytämme välttämättömiä evästeitä ja paikallista tallennusta ylläpitääksemme istuntoasi, muistaaksemme mieltymyksesi (teema, kieli) ja tarjotaksemme sujuvan käyttökokemuksen. Emme käytä kolmansien osapuolten seurantakeksejä.',
  'privacy.thirdParties.title': 'Kolmannen osapuolen palvelut',
  'privacy.thirdParties.body': 'Saatamme käyttää kolmannen osapuolen palveluja tiettyyn toiminnallisuuteen, kuten AI-ominaisuuksiin (Anthropic Claude) ja push-ilmoituksiin. Nämä palvelut noudattavat omia tietosuojakäytäntöjään ja käsittelevät vain vähimmäistietoja, jotka ovat tarpeen.',
  'privacy.rights.title': 'Oikeutesi',
  'privacy.rights.body': 'Sinulla on oikeus päästä käsiksi, korjata, viedä tai poistaa henkilötietosi milloin tahansa. Voit hallita tietojasi Asetuksista tai ottamalla yhteyttä tukitiimiimme.',
  'privacy.contact.title': 'Ota meihin yhteyttä',
  'privacy.contact.body': 'Tietosuojaan liittyvissä kysymyksissä tai tietopyynnöissä ota meihin yhteyttä osoitteessa privacy@chatyy.com.br. Vastaamme 30 päivän kuluessa.',

  // Terms modal
  'terms.title': 'Käyttöehdot',
  'terms.subtitle': 'Ohjeet Chatyy\'n käyttöön',
  'terms.lastUpdated': 'Viimeksi päivitetty: Maaliskuu 2026',
  'terms.acceptance.title': 'Ehtojen hyväksyminen',
  'terms.acceptance.body': 'Pääsemällä tai käyttämällä Chatyy\'tä hyväksyt nämä käyttöehdot. Jos et hyväksy mitään osaa näistä ehdoista, et voi käyttää palvelua.',
  'terms.services.title': 'Palveluiden kuvaus',
  'terms.services.body': 'Chatyy tarjoaa sähköpostiviestintäpalveluja, mukaan lukien sähköpostien lähettämisen, vastaanottamisen ja hallinnan, sekä AI-pohjaisia ominaisuuksia, kalenteriyhteensopivuutta ja videokonferenssikykyjä.',
  'terms.accounts.title': 'Käyttäjätilit',
  'terms.accounts.body': 'Olet vastuussa tilisi tietoturvan ylläpitämisestä. Et saa jakaa salasanaasi tai sallia luvattoman pääsyn tiliisi. Sinun on oltava vähintään 13-vuotias käyttääksesi tätä palvelua.',
  'terms.conduct.title': 'Hyväksyttävä käyttö',
  'terms.conduct.body': 'Sitouduit olemaan käyttämättä palvelua roskapostin, haittaohjelmien, kalastelun tai minkäänlaisen laittoman sisällön lähettämiseen. Et saa yrittää päästä muiden käyttäjien tileille tai häiritä palvelininfrastruktuuria.',
  'terms.content.title': 'Sisällön omistus',
  'terms.content.body': 'Säilytät omistusoikeuden kaikkeen sisältöön, jonka luot ja lähetät palvelun kautta. Emme vaadi omistusoikeutta sähköposteihisi tai liitteisiisi. Saatamme käsitellä sisältöä tarpeen mukaan palvelun tarjoamiseksi.',
  'terms.limitation.title': 'Vastuun rajoitus',
  'terms.limitation.body': 'Chatyy tarjotaan "sellaisena kuin se on". Pyrimme 99,9 % käyttöaikaan, mutta emme takaa keskeytymätöntä palvelua. Emme ole vastuussa mistään epäsuorista, satunnaisista tai seuraamuksista aiheutuvista vahingoista, jotka johtuvat palvelun käytöstäsi.',
  'terms.termination.title': 'Tilin päättäminen',
  'terms.termination.body': 'Saatamme keskeyttää tai lopettaa tilejä, jotka rikkovat näitä ehtoja. Voit poistaa tilisi milloin tahansa Asetuksista. Tilin päättämisen jälkeen tietosi poistetaan 30 päivän kuluessa.',
  'terms.changes.title': 'Muutokset ehtoihin',
  'terms.changes.body': 'Saatamme päivittää näitä ehtoja aika ajoin. Ilmoitamme sinulle merkittävistä muutoksista sähköpostitse tai sovelluksen ilmoituksessa. Jatkuva palvelun käyttö muutosten jälkeen merkitsee hyväksyntää päivitettyihin ehtoihin.',

